<script setup>import UiIcon from './UiIcon.vue';defineProps({ steps:Array, current:Number, review:Boolean });defineEmits(['go']);const icons=['business','website','pages','content','features','hosting','final'];</script>
<template><aside class="progress"><div class="progress-mobile"><span>{{ review ? 'Review' : `${current + 1} of ${steps.length}` }}</span><div><i :style="{width:`${((review ? steps.length : current + 1)/steps.length)*100}%`}"></i></div></div><ol><li v-for="(step,i) in steps" :class="{active:i===current&&!review,done:i<current||review}" :key="step"><button type="button" @click="$emit('go',i)"><b><UiIcon v-if="i===current&&!review" :name="icons[i]"/><span v-else>{{ i<current||review?'✓':i+1 }}</span></b><span>{{ step }}</span></button></li></ol></aside></template>
